def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Extend diagonal runs of non-background colors in both directions.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    for color in set(v for row in grid for v in row if v != bg):
        pts = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == color]
        if color == 7:
            # The 7s form a diagonal guide; continue it past its endpoint.
            pts.sort()
            if len(pts) >= 2:
                dr = pts[-1][0] - pts[-2][0]
                dc = pts[-1][1] - pts[-2][1]
                if abs(dr) == abs(dc) == 1:
                    r, c = pts[-1]
                    while 0 <= r + dr < h and 0 <= c + dc < w:
                        r += dr
                        c += dc
                        if out[r][c] == bg:
                            out[r][c] = 7
        else:
            # Extend diagonal same-color streaks seen in the examples.
            for dr, dc in ((1, 1), (1, -1)):
                for r, c in pts:
                    if (0 <= r-dr < h and 0 <= c-dc < w
                            and grid[r-dr][c-dc] == color):
                        rr, cc = r, c
                        while 0 <= rr+dr < h and 0 <= cc+dc < w:
                            rr += dr
                            cc += dc
                            if out[rr][cc] == bg:
                                out[rr][cc] = color
    return out
